class Solution {
    public int totalSteps(int[] nums){
        Deque<int[]> stack=new ArrayDeque<>();
        int answer=0;
        for(int value:nums){
            int steps=0;
            while(!stack.isEmpty()&&stack.peek()[0]<=value)steps=Math.max(steps,stack.pop()[1]);
            if(!stack.isEmpty())steps++;
            else steps=0;
            answer=Math.max(answer,steps);
            stack.push(new int[]{
                value,steps
            });
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun totalSteps(nums:IntArray):Int{
        val stack=java.util.ArrayDeque<IntArray>();
        var answer=0;
        for(value in nums){
            var steps=0;
            while(stack.isNotEmpty()&&stack.peek()[0]<=value)steps=maxOf(steps,stack.pop()[1]);
            steps=if(stack.isNotEmpty())steps+1 else 0;
            answer=maxOf(answer,steps);
            stack.push(intArrayOf(value,steps))
        };
        return answer
    }
}

